
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_dk87_r1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_dk87_r1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.311762084331594e+00, -4.230792112296474e+00, -4.117460473552397e+00, -3.960723637228381e+00, -3.747655217266390e+00, -3.465039902549230e+00, -3.102979802827539e+00, -2.660947591127097e+00, -2.154707533987370e+00, -1.618137153167602e+00, -1.092087668297050e+00, -7.102715607241520e-01, -6.020897358061736e-01, -5.040761512973150e-01, -3.731861148464232e-01, -2.440655337991546e-01, -1.453062493052276e-01, -8.714317046483015e-02, -6.270818092499236e-02, -5.586873612462834e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


